  VALUES (v_user, 'customer', 'payment.proof_submit', 'payment', _payment_id, jsonb_build_object('proof_id', v_proof_id));
  RETURN jsonb_build_object('proof_id', v_proof_id, 'order_id', v_order.id);
END;
$$;
